const menuButton = document.querySelector('.menu-toggle');
const nav = document.querySelector('.nav');
function renderPrimaryNavigation() {
  if (!nav) return;
  const root = location.pathname.includes('/pages/') ? '../' : './';
  const items = [
    { label: 'Umre', href: 'pages/umre.html' },
    { label: 'Hac', href: 'pages/hac.html' },
    { label: 'Kudüs Turu', href: 'pages/kudus-turu.html' },
    { label: 'Turlar', href: 'pages/turlar.html', children: [
      ['Kültür Turları', 'pages/kultur-turlari.html'],
      ['Yurtdışı Turlar', 'pages/yurtdisi-turlar.html'],
      ['Yurtiçi Turlar', 'pages/yurtici-turlar.html'],
    ] },
    { label: 'Hizmetler', href: 'pages/hizmetler.html', children: [
      ['Vize Danışmanlığı', 'pages/vize.html'],
      ['Uçak Bileti', 'pages/ucak-bileti.html'],
      ['Otel ve Konaklama', 'pages/otel.html'],
    ] },
    { label: 'Kurumsal', href: 'pages/hakkimizda.html', children: [
      ['Hakkımızda', 'pages/hakkimizda.html'],
      ['Ekibimiz', 'pages/ekibimiz.html'],
      ['Belgelerimiz', 'pages/belgelerimiz.html'],
      ['Sık Sorulan Sorular', 'pages/sss.html'],
    ] },
    { label: 'İletişim', href: 'pages/iletisim.html' },
  ];
  nav.replaceChildren();
  nav.dataset.fixedNav = 'true';
  nav.removeAttribute('aria-busy');
  for (const item of items) {
    const link = document.createElement('a');
    link.className = 'nav-link';
    link.href = root + item.href;
    link.textContent = item.label;
    if (!item.children) {
      nav.append(link);
      continue;
    }
    const group = document.createElement('div');
    group.className = 'nav-group nav-parent-group';
    const head = document.createElement('div');
    head.className = 'nav-parent-head';
    link.classList.add('nav-parent-link');
    const trigger = document.createElement('button');
    trigger.className = 'nav-trigger';
    trigger.type = 'button';
    trigger.textContent = '⌄';
    trigger.setAttribute('aria-label', `${item.label} alt menüsünü aç`);
    trigger.setAttribute('aria-expanded', 'false');
    trigger.addEventListener('click', () => {
      const open = group.classList.toggle('open');
      trigger.setAttribute('aria-expanded', String(open));
      nav.querySelectorAll('.nav-group').forEach((other) => {
        if (other !== group) {
          other.classList.remove('open');
          other.querySelector('.nav-trigger')?.setAttribute('aria-expanded', 'false');
        }
      });
    });
    head.append(link, trigger);
    const dropdown = document.createElement('div');
    dropdown.className = 'nav-dropdown';
    for (const [label, href] of item.children) {
      const child = document.createElement('a');
      child.textContent = label;
      child.href = root + href;
      dropdown.append(child);
    }
    group.append(head, dropdown);
    nav.append(group);
  }
  window.ecmelRenderPrimaryNavigationFallback = () => {
    if (nav.childElementCount) return;
    renderPrimaryNavigation();
  };
}
renderPrimaryNavigation();
const headerInner = document.querySelector('.header-inner');
let languageSelect = document.querySelector('.language-select');
if (headerInner && !languageSelect) {
  languageSelect = document.createElement('select');
  languageSelect.className = 'language-select';
  languageSelect.setAttribute('aria-label', 'Dil seçimi');
  languageSelect.innerHTML = '<option value="tr">TR</option><option value="en">EN</option><option value="ar">العربية</option>';
  headerInner.insertBefore(languageSelect, headerInner.querySelector('.header-cta'));
}
if (languageSelect) {
  fetch((location.pathname.includes('/pages/') ? '../' : './') + 'api/public/content', { cache: 'no-store' })
    .then(response => response.ok ? response.json() : null)
    .then(data => {
      if (!data?.settings?.supported_languages) return;
      const languages = JSON.parse(data.settings.supported_languages);
      const saved = localStorage.getItem('ecmel_language') || data.settings.site_language || 'tr';
      languageSelect.innerHTML = languages.map(code => `<option value="${code}">${({tr:'TR',en:'EN',ar:'العربية'}[code] || code.toUpperCase())}</option>`).join('');
      languageSelect.value = languages.includes(saved) ? saved : 'tr';
    }).catch(() => {});
}
const navGroups = () => [...document.querySelectorAll('.nav-group')];
const currentPath = location.pathname.replace(/\/$/, '').replace(/\.html$/, '');
nav?.querySelectorAll('a').forEach((link) => {
  const linkPath = new URL(link.href, location.href).pathname.replace(/\/$/, '').replace(/\.html$/, '');
  if (linkPath === currentPath) link.setAttribute('aria-current', 'page');
});

function closeMenus() {
  navGroups().forEach((group) => {
    group.classList.remove('open');
    group.querySelector('.nav-trigger')?.setAttribute('aria-expanded', 'false');
  });
}

menuButton?.addEventListener('click', () => {
  const isOpen = nav.classList.toggle('open');
  menuButton.setAttribute('aria-expanded', String(isOpen));
  menuButton.setAttribute('aria-label', isOpen ? 'Menüyü kapat' : 'Menüyü aç');
  if (!isOpen) closeMenus();
});

navGroups().forEach((group) => {
  const trigger = group.querySelector('.nav-trigger');
  trigger.addEventListener('click', () => {
    const isOpen = group.classList.toggle('open');
    trigger.setAttribute('aria-expanded', String(isOpen));
    navGroups().filter((other) => other !== group).forEach((other) => {
      other.classList.remove('open');
      other.querySelector('.nav-trigger')?.setAttribute('aria-expanded', 'false');
    });
  });
});

nav?.querySelectorAll('a').forEach((link) => {
  link.addEventListener('click', () => {
    nav.classList.remove('open');
    menuButton?.setAttribute('aria-expanded', 'false');
    menuButton?.setAttribute('aria-label', 'Menüyü aç');
    closeMenus();
  });
});

document.addEventListener('click', (event) => {
  if (!event.target.closest('.nav-group')) closeMenus();
});

document.addEventListener('keydown', (event) => {
  if (event.key === 'Escape') {
    closeMenus();
    nav.classList.remove('open');
    menuButton.setAttribute('aria-expanded', 'false');
    menuButton.setAttribute('aria-label', 'Menüyü aç');
  }
});

document.querySelectorAll('form[data-endpoint]').forEach((form) => {
  form.addEventListener('submit', async (event) => {
    event.preventDefault(); const note=form.querySelector('.form-note'); const submit=form.querySelector('[type="submit"]');
    if(form.elements.website?.value)return;
    submit.disabled=true; if(note)note.textContent='Gönderiliyor…';
    try { const response=await fetch(form.dataset.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))}); const result=await response.json(); if(!response.ok)throw Error(result.error||'Gönderim tamamlanamadı.'); form.reset(); window.grecaptcha?.reset(); if(note)note.textContent=result.message||'Talebiniz alındı.'; }
    catch(error){window.grecaptcha?.reset();if(note)note.textContent=error.message||'Bağlantı kurulamadı. Lütfen telefonla ulaşın.';}
    finally{submit.disabled=false;}
  });
});

const hero = document.querySelector('.hero');
let heroSlides = [...document.querySelectorAll('.hero-slide')];
let heroSlideControls = [...document.querySelectorAll('.hero-slide-control')];
if (hero && heroSlides.length > 0 && heroSlides.length === heroSlideControls.length) {
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  let activeSlide = 0;
  let rotationTimer = null;

  function showHeroSlide(index) {
    activeSlide = (index + heroSlides.length) % heroSlides.length;
    [activeSlide, (activeSlide + 1) % heroSlides.length].forEach(i => { const image=heroSlides[i].querySelector('img[data-src]'); if(image){image.src=image.dataset.src;image.removeAttribute('data-src');} });
    hero.classList.toggle('is-heritage-slide', heroSlides[activeSlide].classList.contains('hero-slide-heritage'));
    hero.classList.toggle('is-wide-panorama', heroSlides[activeSlide].classList.contains('hero-slide-panorama'));
    heroSlides.forEach((slide, slideIndex) => {
      slide.classList.toggle('is-active', slideIndex === activeSlide);
    });
    heroSlideControls.forEach((control, slideIndex) => {
      const isActive = slideIndex === activeSlide;
      control.classList.toggle('is-active', isActive);
      control.setAttribute('aria-pressed', String(isActive));
    });
  }

  function stopHeroRotation() {
    window.clearInterval(rotationTimer);
    rotationTimer = null;
  }

  function startHeroRotation() {
    stopHeroRotation();
    if (heroSlides.length < 2 || reduceMotion.matches || document.hidden) return;
    rotationTimer = window.setInterval(() => showHeroSlide(activeSlide + 1), 7600);
  }

  window.ecmelSetHeroImages = (images) => {
    if (!Array.isArray(images) || !images.length) return;
    const photo=hero.querySelector('.hero-photo'), controls=hero.querySelector('.hero-slider-controls'), templates=heroSlides.slice();
    const nextSlides=images.map((src,index)=>{const slide=(templates[index]||templates[0]).cloneNode(true);slide.classList.remove('is-active');const image=slide.querySelector('img');image.src=src;image.removeAttribute('data-src');return slide});
    const nextControls=images.map((src,index)=>{const button=document.createElement('button');button.type='button';button.className='hero-slide-control';button.dataset.slideTo=String(index);button.setAttribute('aria-label',`Slayt ${index+1} görselini göster`);button.setAttribute('aria-pressed','false');button.addEventListener('click',()=>{showHeroSlide(index);startHeroRotation()});return button});
    photo.replaceChildren(...nextSlides);controls.replaceChildren(...nextControls);heroSlides=nextSlides;heroSlideControls=nextControls;showHeroSlide(0);startHeroRotation();
  };

  showHeroSlide(0);
  heroSlideControls.forEach((control) => {
    control.addEventListener('click', () => {
      showHeroSlide(Number(control.dataset.slideTo));
      startHeroRotation();
    });
  });
  document.addEventListener('visibilitychange', startHeroRotation);
  reduceMotion.addEventListener?.('change', startHeroRotation);
  startHeroRotation();
}

