const supportedLanguages = ['tr', 'en', 'ar'];
const getLanguage = () => supportedLanguages.includes(localStorage.getItem(languageStorageKey)) ? localStorage.getItem(languageStorageKey) : 'tr';
const trimPattern = /^(\s*)([\s\S]*?)(\s*)$/;
function translateTextNode(node, locale) {
  if (!originalTextNodes.has(node)) originalTextNodes.set(node, node.nodeValue);
  const source = originalTextNodes.get(node);
  const match = source.match(trimPattern);
  const translation = locale === 'tr' ? match[2] : languageRows[match[2]]?.[locale === 'en' ? 0 : 1];
  if (translation) node.nodeValue = `${match[1]}${translation}${match[3]}`;
}
function applyLanguage(locale = getLanguage()) {
  locale = supportedLanguages.includes(locale) ? locale : 'tr';
  document.documentElement.lang = locale === 'ar' ? 'ar' : locale;
  document.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr';
  if (languageSelect) languageSelect.value = locale;
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let textNode;
  while ((textNode = walker.nextNode())) {
    if (textNode.parentElement?.closest('script,style,code,pre,[data-no-translate]')) continue;
    translateTextNode(textNode, locale);
  }
  document.querySelectorAll('[aria-label],[placeholder],[alt],[title]').forEach((element) => {
    ['aria-label', 'placeholder', 'alt', 'title'].forEach((attribute) => {
      if (!element.hasAttribute(attribute)) return;
      if (!originalAttributes.has(element)) originalAttributes.set(element, {});
      const values = originalAttributes.get(element);
      if (!(attribute in values)) values[attribute] = element.getAttribute(attribute);
      const source = values[attribute];
      const translated = locale === 'tr' ? source : languageRows[source]?.[locale === 'en' ? 0 : 1];
      if (translated) element.setAttribute(attribute, translated);
    });
  });
  const pageTitle = document.querySelector('title');
  if (pageTitle) {
    if (!pageTitle.dataset.sourceTitle) pageTitle.dataset.sourceTitle = pageTitle.textContent;
    const translated = locale === 'tr' ? pageTitle.dataset.sourceTitle : languageRows[pageTitle.dataset.sourceTitle]?.[locale === 'en' ? 0 : 1];
    if (translated && pageTitle.textContent !== translated) pageTitle.textContent = translated;
  }
  const description = document.querySelector('meta[name="description"]');
  if (description) {
    if (!description.dataset.sourceContent) description.dataset.sourceContent = description.content;
    const translated = locale === 'tr' ? description.dataset.sourceContent : languageRows[description.dataset.sourceContent]?.[locale === 'en' ? 0 : 1];
    if (translated) description.content = translated;
  }
}
window.ecmelApplyLanguage = applyLanguage;
languageSelect?.addEventListener('change', () => {
  localStorage.setItem(languageStorageKey, languageSelect.value);
  applyLanguage(languageSelect.value);
});

async function loadGuestReviews(){const target=document.querySelector('[data-review-list]');if(!target)return;try{const response=await fetch('/api/public/reviews');if(!response.ok)return;const rows=await response.json();if(!rows.length){target.hidden=true;return}target.innerHTML=rows.map(row=>`<blockquote class="review-card"><span>“</span><p>${escapeHTML(row.review)}</p><cite>${escapeHTML(row.name)}<small>${escapeHTML(row.trip||'Misafir yorumu')}</small></cite></blockquote>`).join('')}catch{}}
function escapeHTML(value=''){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
loadGuestReviews();

function installCookieNotice() {
  const consentKey = 'ecmel_cookie_consent';
  let saved = null;
  try { saved = JSON.parse(localStorage.getItem(consentKey) || 'null'); } catch {}
  if (saved && (saved.expires <= Date.now() || saved.version !== 2)) {
    localStorage.removeItem(consentKey);
    saved = null;
  }
  const banner = document.createElement('section');
  banner.className = 'cookie-banner';
  banner.setAttribute('role', 'dialog');
  banner.setAttribute('aria-modal', 'false');
  banner.setAttribute('aria-labelledby', 'cookie-title');
  banner.hidden = Boolean(saved);
  banner.innerHTML = '<div class="cookie-copy"><h2 id="cookie-title">Çerez tercihleriniz</h2><p>Sitemiz, tercihinizi hatırlamak için gerekli tarayıcı depolamasını kullanır. İsteğe bağlı ziyaret istatistikleri yalnızca kabulünüzden sonra çalışır. Reddetmeniz temel site kullanımını etkilemez. <a href="/pages/cerez-politikasi.html">Çerez politikası</a></p></div><div class="cookie-actions"><button type="button" data-consent="reject">Reddet</button><button type="button" data-consent="accept">Kabul et</button></div>';
  document.body.append(banner);
  const saveChoice = (analytics) => {
    const choice = { version: 2, analytics, updated: Date.now(), expires: Date.now() + 180 * 24 * 60 * 60 * 1000 };
    try { localStorage.setItem(consentKey, JSON.stringify(choice)); } catch {}
    banner.hidden = true;
    window.dispatchEvent(new CustomEvent('ecmel:consent-changed', { detail: choice }));
  };
  banner.querySelector('[data-consent="accept"]').addEventListener('click', () => saveChoice(true));
  banner.querySelector('[data-consent="reject"]').addEventListener('click', () => saveChoice(false));
  const preferenceLink = document.createElement('button');
  preferenceLink.type = 'button';
  preferenceLink.className = 'cookie-preferences-link';
  preferenceLink.textContent = 'Çerez tercihleri';
  preferenceLink.addEventListener('click', () => { banner.hidden = false; banner.querySelector('[data-consent="reject"]').focus(); });
  document.querySelector('.footer-bottom')?.append(preferenceLink);
}
installCookieNotice();
