(async()=>{
  const path=location.pathname.split('/').filter(Boolean);const slug=path.at(-1)?.replace(/\.html$/,'')||'home';if(slug!=='sss')return;
  try{
    const root=path.length>1?'../':'./';const response=await fetch(root+'api/public/content',{cache:'no-store'});if(!response.ok)return;
    const data=await response.json();const locale=['tr','en','ar'].includes(localStorage.getItem('ecmel_language'))?localStorage.getItem('ecmel_language'):'tr';let localized={};try{localized=JSON.parse(data.settings?.translations_json||'{}')[locale]||{}}catch{}
    const page=(data.pages||[]).find(item=>item.slug==='sss');const raw=localized.pages?.sss?.content||page?.content;let model;try{model=JSON.parse(raw||'{}')}catch{};const items=model?.faqs;if(!Array.isArray(items)||!items.length||document.querySelector('.cms-faq-list .cms-faq-item'))return;
    const section=document.createElement('section');section.className='cms-faq-list';const heading=document.createElement('h2');heading.textContent=locale==='en'?'Frequently asked questions':locale==='ar'?'الأسئلة الشائعة':'Sık Sorulan Sorular';section.append(heading);
    for(const item of items){if(!item?.question||!item?.answer)continue;const details=document.createElement('details');details.className='cms-faq-item';const question=document.createElement('summary');question.textContent=item.question;const answer=document.createElement('p');answer.textContent=item.answer;details.append(question,answer);section.append(details)}
    const host=document.querySelector('main .page-content')||document.querySelector('main');const before=host?.querySelector('.page-highlights');if(host)host.insertBefore(section,before||null);
  }catch(error){console.warn('FAQ içeriği yüklenemedi.',error)}
})();
